import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Publishing public npm tools","description":"","frontmatter":{"navigation":{"category":"CI and releases"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/npm-publishing.md"},"headers":[],"relativePath":"guides/npm-publishing.md","filePath":"docs/npm-publishing.md","lastUpdated":1792014225000}`),a={name:`guides/npm-publishing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="publishing-public-npm-tools" tabindex="-1">Publishing public npm tools <a class="header-anchor" href="#publishing-public-npm-tools" aria-label="Permalink to “Publishing public npm tools”">​</a></h1><p>The public npm package set and dependency order are defined in <a href="../scripts/utils/tool-packages.mjs"><code>tool-packages.mjs</code></a>. Use that source for the current names, workspace paths, and release order; this guide does not duplicate the list.</p><p>For initial setup, publish metadata-only placeholders at <code>0.0.0</code>. Release Please produces and the GitHub Actions release workflow publishes the first functional release for each package.</p><h2 id="seed-package-names" tabindex="-1">Seed package names <a class="header-anchor" href="#seed-package-names" aria-label="Permalink to “Seed package names”">​</a></h2><p>npm requires a package to exist before a trusted publisher can be configured. Publish one <code>0.0.0</code> placeholder for every package in the canonical list before setting up trusted publishing. Each placeholder contains only <code>package.json</code> and a README that says the package is non-functional. It must not contain runtime code, commands, or package dependencies.</p><p>Publish each verified placeholder tarball with the <code>placeholder</code> dist-tag:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">placeholder-tarbal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --access</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=placeholder</span></span></code></pre></div><p>The registry also assigns the first published version to <code>latest</code>, so both tags point to <code>0.0.0</code> until the first functional release. The release workflow publishes without a non-default tag, moving <code>latest</code> to the functional version while <code>placeholder</code> remains on <code>0.0.0</code>.</p><p>Run direct npm commands from outside the repository root, such as <code>/tmp</code>, to avoid the root <code>devEngines</code> package-manager requirement. Confirm the exact package name and <code>0.0.0</code> version on the public registry after each publish. Do not republish a placeholder version with different bytes; npm versions are immutable.</p><h2 id="publish-functional-releases" tabindex="-1">Publish functional releases <a class="header-anchor" href="#publish-functional-releases" aria-label="Permalink to “Publish functional releases”">​</a></h2><p>Release Please creates the first functional release PR for each registered tool. The configured first functional version is <code>0.1.0</code>. Merge release PRs in the canonical order from <a href="../scripts/utils/tool-packages.mjs"><code>tool-packages.mjs</code></a>, so each consumer&#39;s required public dependencies are available before its publish job runs.</p><p>The <code>ci.yml</code> caller invokes the reusable release workflow after CI gates pass. Its <code>publish-tools</code> job runs only when Release Please reports public tool paths to release. The job packs and validates those packages sequentially, checks exact dependency versions and registry integrity, then publishes missing versions with npm trusted publishing and provenance. See <a href="./npm-trusted-publishing">Trusted publishing for npm tools</a> for setup and recovery.</p><p>Configure trust for a package only after its placeholder exists and its real Release Please release is ready. The first successful OIDC publish must complete within two days of creating the relationship. Publishing the existing <code>0.0.0</code> placeholder again does not validate OIDC.</p><p><code>pnpm npm:bootstrap</code> is available as a manual exact-tag fallback for a maintainer who must publish a <code>0.1.0</code> artifact directly. It validates the tagged source and package but does not configure npm trust. The normal first functional release uses the Release Please workflow above.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};